typedef unsigned __int128 uint128_t;

uint128_t multiply128(uint64_t x, uint64_t y) {
  uint128_t result;
  asm (
    "movq %1, %%rax\n\t" // Move x to %rax
    "mulq %2\n\t"       // Perform unsigned multiplication
    "movq %%rax, %0\n\t" // Store lower 64 bits in result
    "movq %%rdx, %0+8"   // Store upper 64 bits in result+8
    : "=m" (result)      // Output
    : "rm" (x), "rm" (y) // Input
    : "%rax", "%rdx"    // Clobbered registers
  );
  return result;
}

